void repo_init_revisions ( struct repository * r , struct rev_info * revs , const char * prefix ) { struct rev_info blank = REV_INFO_INIT ; memcpy ( revs , & blank , sizeof ( * revs ) ) ; revs -> repo = r ; revs -> pruning . repo = r ; revs -> pruning . add_remove = file_add_remove ; revs -> pruning . change = file_change ; revs -> pruning . change_fn_data = revs ; revs -> prefix = prefix ; grep_init ( & revs -> grep_filter , revs -> repo ) ; revs -> grep_filter . status_only = 1 ; repo_diff_setup ( revs -> repo , & revs -> diffopt ) ; if ( prefix && ! revs -> diffopt . prefix ) { revs -> diffopt . prefix = prefix ; revs -> diffopt . prefix_length = strlen ( prefix ) ; } init_display_notes ( & revs -> notes_opt ) ; list_objects_filter_init ( & revs -> filter ) ; } 